/*The BankCrad is a card that can deposit or withdraw money.*/
class BankCard {
  /*The unique identifier of the bank card*/
  CardID: number;
  /*The status of the bank card*/
  CardStatus: CardStatus;
  /*The catalog of the bank card*/
  Catalog: CardCatalog;
  /*The password of the bank card*/
  Password: number;
  /*The balance of the bank card*/
  Balance: number;
  /*The user who owns the bank card*/
  BelongedUser: User;
}
/*Bank user information.*/
class User {
  /*The id of the user*/
  UserID: number;
  /*The name of the user*/
  Name: string;
  /*The address of the user*/
  Address: string;
  /*The bank card owned by the user*/
  OwnedCard: BankCard;
}
enum CardStatus {
  NORMAL = "NORMAL",
  SUSPEND = "SUSPEND",
  CANNEL = "CANNEL",
}
enum CardCatalog {
  CREDIT = "CREDIT",
  DESPOSIT = "DESPOSIT",
}
const map = new Map();
map.set(BankCard, []);
map.set(User, []);
const getRepository = <T,>(clazz: new (...args: any[]) => T) => {
  return map.get(clazz) as T[];
};
export { CardStatus, CardCatalog, BankCard, User, getRepository };

typescript.originalService:
class AutomatedTellerMachineSystem_AutoGenerated {
  /*SystemVariable Start*/
  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*The input card exist and the card id is validated,
   *then validate if the input password is equal to the card password.
   **/
  inputPassword(password: number): boolean {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.CardIDValidated === true,
              description: "o.CardIDValidated=true",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->any(o|o.CardIDValidated=true)",
    }).build().pass;
    let isValidPassword: boolean = l({
      logic: () => inputCard.Password === password,
      description: "inputCard.Password=password",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(inputCard) === false,
        description: "inputCard.oclIsUndefined()=false",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let result: boolean;
    return l({
      execute: () =>
        (inputCard.Balance = inputCard.Balance + this.DepositedNumber),
      description: "inputCard.Balance=inputCard.Balance+DepositedNumber",
    }).build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

